"use client";
import { useState } from "react";

type AccordeonItems = {
  id: number;
  title: string;
  content: string;
};

export default function Accordion2() {
  const [isOpen, setIsOpen] = useState<number | null>(null);

  const items: AccordeonItems[] = [
    {
      id: 1,
      title: "title1",
      content:
        "Lorem ipsum dolor sit amet consectetur adipisicing elit. Aliquid, laboriosam quidem vero deleniti numquam pariatur obcaecati suscipit vel molestiae eaque, ex quo perferendis ut consequuntur officiis odio magnam necessitatibus neque.",
    },
    {
      id: 2,
      title: "title2",
      content:
        "maiores quasi consequatur mollitia corrupti tempora quam eum facilis accusantium quis saepe",
    },
    {
      id: 3,
      title: "title3",
      content:
        "elit. Aliquid, laboriosam quidem vero deleniti numquam pariatur obcaecati suscipit vel molestiae eaque, ex quo perferendis ut consequuntur officiis odio magnam necessitatibus neque.",
    },
  ];

  const handleOpenContent = (id: number) => {
    setIsOpen((prev) =>  (prev === id ? null : id));
  }

  return (
    <div className="flex justify-center items-center mx-auto">
      <div className="w-[300px] mx-auto">
        {items.map((item) => (
          <div key={item.id}>
            <button onClick={() => handleOpenContent(item.id)} className="bg-blue-200 border border-blue-400 w-full">
              {item.title}{isOpen === item.id ? "-" : "+"}
            </button>

            {item.id === isOpen && <div>{item.content}</div>}
          </div>
        ))}
      </div>
    </div>
  );
}
